from typing import TypedDict, Literal

CategoryType = Literal[
    "general_chat",
    "general_knowledge",
    "project_fact",
    "task_create",
    "task_modify",
    "soft_warning",
    "hard_constraint",
    "confirmation",
    "emergency_control",
    "ASR",
    "concurrency",
    "persistence",
]

NatureType = Literal["invariant", "expected_behavior", "known_defect"]


class CorpusCase(TypedDict):
    id: str
    category: CategoryType
    input: str
    nature: NatureType
    expected_effect: str
    slot_mutation: str
    should_publish: bool


